/* B: annotated study reference. Blue-gray frame, white sheets, ink-blue
   hierarchy, amber annotations. Correct/incorrect colours retain their meaning. */

/* fonts (bundled, SIL Open Font License; see fonts/OFL.txt) */
@font-face { font-family: "DM Sans"; font-style: normal; font-weight: 100 1000; font-display: swap; src: url("fonts/dmsans.woff2") format("woff2"); }
@font-face { font-family: "DM Mono"; font-style: normal; font-weight: 400; font-display: swap; src: url("fonts/dmmono-400.woff2") format("woff2"); }
@font-face { font-family: "DM Mono"; font-style: normal; font-weight: 500; font-display: swap; src: url("fonts/dmmono-500.woff2") format("woff2"); }

:root {
  color-scheme: light;
  --bg: #ffffff;
  --frame: #edf2f6;
  --panel: #f1f5f8;
  --ink: #173f63;
  --text: #263e52;
  --muted: #526a7e;
  --faint: #60758a;
  --line: #d5e0e8;
  --line-strong: #aebfcf;
  --accent: #173f63;
  --accent-ink: #ffffff;
  --green: #2e7d4f;
  --green-bg: #eef6f1;
  --amber: #9a6700;
  --amber-bg: #fbf4e4;
  --red: #b3352b;
  --red-bg: #faeeed;
  --sans: "DM Sans", "Segoe UI", "Helvetica Neue", Arial, "PingFang TC", "Microsoft JhengHei", "Noto Sans TC", sans-serif;
  --mono: "DM Mono", "SFMono-Regular", Consolas, Menlo, monospace;
  --r: 4px;
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #14212e;
  --frame: #0e1924;
  --panel: #1c2e3e;
  --ink: #dceaf5;
  --text: #d0dce5;
  --muted: #a6bdcf;
  --faint: #91a9be;
  --line: #354a5c;
  --line-strong: #5c768b;
  --accent: #f2f2f2;
  --accent-ink: #0f0f0f;
  --green: #6fbf8f;
  --green-bg: #16241c;
  --amber: #d9a43b;
  --amber-bg: #2a2314;
  --red: #e07068;
  --red-bg: #2b1a18;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body { background: var(--bg); color: var(--text); font: 15.5px/1.55 var(--sans); -webkit-font-smoothing: antialiased; }
button { font: inherit; color: inherit; }
b, strong { font-weight: 600; color: var(--ink); }
.loading { text-align: center; padding: 4rem; color: var(--muted); }
.wrap { max-width: 960px; margin: 0 auto; padding: 24px 24px 80px; }
.note { font-size: 13px; color: var(--muted); }
.footer { text-align: center; color: var(--faint); font-size: 12px; margin-top: 48px; max-width: 78ch; margin-inline: auto; text-wrap: balance; }
.ic { width: 1em; height: 1em; vertical-align: -.15em; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }

/* small grey caption */
.eyebrow, .tlabel, .subhead, .omr-mod, .brand .t2 {
  font-size: 11px; font-weight: 500; letter-spacing: .8px; text-transform: uppercase; color: var(--faint);
}

/* ---------- top bar ---------- */
.topbar { position: sticky; top: 0; z-index: 30; background: var(--bg); border-bottom: 1px solid var(--line); }
.topbar .wrap { padding-top: 14px; padding-bottom: 14px; display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.brand { flex: 1 1 auto; min-width: 240px; }
.brand .t1 { font-weight: 600; font-size: 16px; color: var(--ink); line-height: 1.3; }
.brand .t2 { margin-top: 2px; }
.topctl { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r); padding: 2px; }
.seg button { border: 0; background: transparent; color: var(--muted); font-size: 13px; padding: 4px 11px; border-radius: 4px; cursor: pointer; }
.seg button.on { background: var(--accent); color: var(--accent-ink); }
.seg button:not(.on):hover { color: var(--ink); }

/* ---------- sections ---------- */
.card { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r); padding: 28px; margin-top: 20px; }
.card h2 { margin: 0 0 6px; font-size: 20px; font-weight: 600; color: var(--ink); letter-spacing: -.2px; }
.card .sub { color: var(--muted); font-size: 14px; margin-bottom: 16px; }
.rulebox { background: var(--panel); border-radius: var(--r); padding: 12px 16px; font-size: 14px; margin-top: 14px; }
.subhead { margin: 26px 0 10px; }

/* ---------- buttons & chips ---------- */
button.btn {
  border: 1px solid var(--accent); border-radius: var(--r); cursor: pointer;
  padding: 9px 16px; font-weight: 500; font-size: 14px; line-height: 20px;
  background: var(--accent); color: var(--accent-ink);
  display: inline-flex; align-items: center; gap: 8px;
}
button.btn:hover { opacity: .85; }
button.btn.secondary { background: transparent; color: var(--ink); border-color: var(--line-strong); }
button.btn.secondary:hover { opacity: 1; border-color: var(--ink); }
button.btn.danger { background: transparent; color: var(--red); border-color: var(--red); }
button.btn.small { padding: 6px 12px; font-size: 13px; line-height: 18px; }
button.btn:disabled { opacity: .35; cursor: default; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip { font-size: 13px; border: 1px solid var(--line-strong); border-radius: 999px; background: transparent; color: var(--text); padding: 5px 13px; cursor: pointer; }
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip.on { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.actions { display: flex; gap: 10px; margin-top: 18px; flex-wrap: wrap; align-items: center; }

/* ---------- welcome ---------- */
.welcome { text-align: center; padding: 48px 28px; }
.welcome h2 { font-size: 24px; font-weight: 600; margin: 8px 0 26px; }
.profiles { display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; }
.profile-card { flex: 1 1 220px; max-width: 280px; border: 1px solid var(--line); border-radius: var(--r); padding: 28px 20px; cursor: pointer; text-align: center; }
.profile-card:hover { border-color: var(--ink); }
.profile-card .avatar { font-size: 30px; font-weight: 600; color: var(--ink); line-height: 1.1; }
.profile-card .name { font-size: 16px; font-weight: 600; margin-top: 10px; color: var(--ink); }
.profile-card .paper { color: var(--muted); font-size: 13px; margin-top: 2px; }

/* ---------- history table ---------- */
.tablewrap { overflow-x: auto; -webkit-overflow-scrolling: touch; }
table.hist { width: 100%; border-collapse: collapse; font-size: 14px; }
table.hist th, table.hist td { text-align: left; padding: 11px 12px; border-bottom: 1px solid var(--line); }
table.hist th { color: var(--faint); font-weight: 500; font-size: 11px; letter-spacing: .6px; text-transform: uppercase; white-space: nowrap; }
table.hist td.num { font-family: var(--mono); font-size: 13.5px; color: var(--ink); }
.tag { display: inline-block; font-size: 12.5px; font-weight: 600; }
.tag.pass { color: var(--green); }
.tag.fail { color: var(--red); }
.modcells { display: inline-flex; gap: 3px; vertical-align: middle; }
.modcells i { width: 20px; height: 20px; border-radius: 4px; font-style: normal; font-family: var(--mono); font-size: 11px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--line); color: var(--muted); }
.modcells i.bad { border-color: var(--red); color: var(--red); }

/* ---------- question ---------- */
.stem { font-size: 17.5px; line-height: 1.55; color: var(--ink); margin-bottom: 8px; max-width: 68ch; }
.tcline { display: block; color: var(--muted); font-size: .94em; margin-top: 4px; }
.opt .tcline { font-size: .92em; margin-top: 2px; }
/* the numbered statements of a combination question, set like the printed paper:
   the options below name subsets of these by number, so the numbers must read
   clearly and stay attached to their line. */
.stmts { margin: 4px 0 0; padding-left: 0; list-style: none; counter-reset: stmt; max-width: 68ch; }
.stmts li {
  counter-increment: stmt; position: relative; padding-left: 30px; margin-top: 9px;
  font-size: 15.5px; line-height: 1.5; color: var(--ink);
}
.stmts li::before {
  content: counter(stmt) "."; position: absolute; left: 0; top: 0;
  font-family: var(--mono); font-size: 12.5px; color: var(--muted);
}
.stmts .tcline { font-size: .93em; }
/* once answered, each statement is marked correct or not, with its trap and note */
.st-verdict { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 3px; font-size: 13px; font-weight: 600; }
.st-true .st-verdict { color: var(--green); }
.st-false .st-verdict { color: var(--red); }
.st-verdict .trap { font-weight: 500; color: var(--amber); }
.st-note { margin-top: 2px; font-size: 13.5px; line-height: 1.5; color: var(--muted); }
.st-note .tcline { font-size: 1em; }
.opts.tf { flex-direction: row; flex-wrap: wrap; }
.opts.tf .opt { flex: 1 1 160px; }
.opts { display: flex; flex-direction: column; gap: 8px; margin-top: 18px; }
.opt {
  display: flex; gap: 14px; align-items: flex-start; text-align: left; width: 100%;
  font-size: 15px; line-height: 1.5; border: 1px solid var(--line); border-radius: var(--r);
  background: transparent; padding: 12px 14px; cursor: pointer;
}
.opt:hover { border-color: var(--ink); }
.opt .letter {
  flex: 0 0 auto; width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--line-strong);
  display: inline-flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 12px; color: var(--muted); margin-top: 1px;
}
.opt .otext { flex: 1; }
.opt.sel { border-color: var(--ink); }
.opt.sel .letter { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.opt.correct { border-color: var(--green); }
.opt.correct .letter { background: var(--green); border-color: var(--green); color: #fff; }
.opt.wrong { border-color: var(--red); }
.opt.wrong .letter { background: var(--red); border-color: var(--red); color: #fff; }
.opt.dim { opacity: .6; }
.opt:disabled { cursor: default; }
.opt:disabled:hover { border-color: var(--line); }
.opt.correct:disabled:hover { border-color: var(--green); }
.opt.wrong:disabled:hover { border-color: var(--red); }
.opt.sel:disabled:hover { border-color: var(--ink); }

.explain { margin-top: 18px; background: var(--panel); border-radius: var(--r); padding: 14px 16px; font-size: 14px; line-height: 1.55; }
.explain .verdict { font-weight: 600; margin-bottom: 6px; }
.explain .verdict.good, .verdict.good { color: var(--green); }
.explain .verdict.bad, .verdict.bad { color: var(--red); }
.explain .cite { margin-top: 10px; font-family: var(--mono); font-size: 12px; color: var(--muted); }
.explain .cite b { color: var(--text); font-weight: 500; }

/* ---------- exam room ---------- */
.examtop { position: sticky; top: 0; z-index: 20; background: var(--bg); border-bottom: 1px solid var(--line); }
.examtop .wrap { display: flex; align-items: center; gap: 14px; padding-top: 10px; padding-bottom: 10px; flex-wrap: wrap; }
.examtop .grow { flex: 1; }
.examtop .prog { font-size: 13px; color: var(--muted); }
.timer { font-family: var(--mono); font-size: 22px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--ink); display: inline-flex; align-items: center; gap: 8px; }
.timer .ic { width: .8em; height: .8em; color: var(--faint); }
.timer.warn { color: var(--amber); }
.timer.crit { color: var(--red); animation: pulse 1s infinite; }
@keyframes pulse { 50% { opacity: .5; } }

.examgrid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px; align-items: start; }
.rail { display: flex; flex-direction: column; gap: 14px; }
.rail .card { margin-top: 0; padding: 18px 20px; }
.rail .timer { font-size: 30px; margin-top: 6px; }
.tprog { height: 2px; background: var(--line); margin-top: 12px; overflow: hidden; }
.tprog i { display: block; height: 100%; width: 0; background: var(--ink); transition: width .5s linear; }
.rail .meta { display: flex; justify-content: space-between; font-size: 13px; color: var(--muted); margin-top: 10px; }
.rail .meta b { font-family: var(--mono); font-weight: 500; }

/* a setting offered above the action buttons */
.optrow { display: flex; gap: 10px; align-items: flex-start; margin-top: 14px; font-size: 14px; line-height: 1.5; color: var(--muted); cursor: pointer; max-width: 68ch; }
.optrow input { margin: 2px 0 0; flex: 0 0 auto; accent-color: var(--accent); width: 15px; height: 15px; }
.optrow b { color: var(--ink); font-weight: 600; }

.railbtns { display: flex; gap: 8px; flex-wrap: wrap; }
.railbtns .btn { flex: 1 1 auto; justify-content: center; }
@media (min-width: 960px) {
  .examtop { display: none; }
  /* rail = sheet (2 × 158px + 12px gap) + card padding (2 × 18px) + borders + room for a 17px scrollbar */
  .examgrid { grid-template-columns: minmax(0, 1fr) 388px; gap: 24px; }
  .rail { position: sticky; top: 84px; max-height: calc(100vh - 100px); overflow-y: auto; overflow-x: hidden; scrollbar-gutter: stable; }
}
.rail .card { padding: 16px 18px; }

.qcard { border: 1px solid var(--line); border-radius: var(--r); padding: 28px; margin-top: 20px; }
.examgrid .qcard { margin-top: 0; }
.qmeta { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }
.qnum { font-size: 18px; font-weight: 600; color: var(--ink); white-space: nowrap; }
.qmod { font-size: 12.5px; color: var(--muted); }
.qflag {
  margin-left: auto; font-size: 13px; border: 1px solid var(--line-strong); background: transparent; border-radius: 999px;
  padding: 4px 12px; cursor: pointer; color: var(--muted); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px;
}
.qflag:hover { color: var(--ink); border-color: var(--ink); }
.qflag.on { border-color: var(--amber); color: var(--amber); }
.qnav-row { display: flex; gap: 10px; margin-top: 20px; align-items: center; flex-wrap: wrap; }
.qnav-row .grow { flex: 1; }
.kbd { font-size: 12.5px; color: var(--faint); }

/* the answer sheet, drawn like the machine-read sheet.
   Every row is a fixed grid — number, five bubbles, a permanent flag slot —
   so a flagged row is exactly as wide as any other (158px). */
.omr { display: grid; grid-template-columns: repeat(2, 158px); justify-content: space-between; gap: 6px 12px; margin-top: 8px; }
.omr-group { break-inside: avoid; }
.omr-mod { margin: 8px 0 4px 2px; }
.omr-row { display: grid; grid-template-columns: 22px repeat(5, 20px) 12px; gap: 4px; align-items: center; padding: 1px 0; border-radius: 4px; }
.omr-row.current { background: var(--panel); }
.omr-num { text-align: right; font-family: var(--mono); font-size: 11.5px; color: var(--faint); background: transparent; border: 0; padding: 0; cursor: pointer; }
.omr-row.current .omr-num { color: var(--ink); }
.bub {
  width: 20px; height: 20px; border-radius: 50%; border: 1px solid var(--line-strong); background: transparent;
  font-family: var(--mono); font-size: 10px; color: var(--faint); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; padding: 0;
}
.bub:hover { border-color: var(--ink); color: var(--ink); }
.bub.on { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.omr-row .fl { font-size: 12px; line-height: 1; display: inline-flex; justify-content: center; color: var(--amber); }
.omr-legend { font-size: 12px; color: var(--faint); margin-top: 10px; }
@media (max-width: 959px) { .omr { grid-template-columns: repeat(auto-fill, 158px); justify-content: start; gap: 6px 20px; } }

/* ---------- results ---------- */
.banner { border: 1px solid var(--line); border-radius: var(--r); padding: 28px; margin-top: 20px; display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.banner .verdict { font-size: 28px; font-weight: 600; letter-spacing: -.3px; }
.banner.pass .verdict { color: var(--green); }
.banner.fail .verdict { color: var(--red); }
.banner .score { font-family: var(--mono); font-size: 44px; font-weight: 500; line-height: 1; color: var(--ink); margin-left: auto; }
.banner .score small { font-size: 18px; color: var(--muted); }
.banner .why { flex-basis: 100%; font-size: 14px; color: var(--muted); }

.dotrows { display: flex; flex-direction: column; gap: 12px; }
.dotrow { display: grid; grid-template-columns: minmax(160px, 1.3fr) auto 1fr; gap: 14px; align-items: center; font-size: 14px; }
.dotrow.breach .dlabel { color: var(--red); }
.dots { display: inline-flex; align-items: center; gap: 6px; }
.dot { width: 14px; height: 14px; border-radius: 50%; display: inline-block; }
.dot.ok { background: var(--ink); }
.dot.bad { background: var(--red); }
.dots .floor { width: 1px; height: 20px; background: var(--line-strong); margin: 0 4px; }
.dnum { color: var(--muted); font-family: var(--mono); font-size: 12.5px; }
.dnum .ok { color: var(--muted); }
.dnum .bad { color: var(--red); }
.ncell {
  width: 32px; height: 32px; border-radius: 4px; border: 1px solid var(--line); background: transparent;
  font-family: var(--mono); font-size: 12px; color: var(--muted); cursor: pointer; display: inline-flex; align-items: center; justify-content: center;
}
.ncell:hover { border-color: var(--ink); }
.ncell.rok { color: var(--ink); }
.ncell.rbad { border-color: var(--red); color: var(--red); }
.review-item { margin-top: 14px; }
.review-item .stem { font-size: 16.5px; }

/* ---------- progress ---------- */
.spark { width: 100%; height: 72px; display: block; margin: 6px 0; overflow: visible; }
.spark .pass-line { stroke: var(--line-strong); stroke-dasharray: 4 4; stroke-width: 1; }
.spark .line { fill: none; stroke: var(--ink); stroke-width: 1.5; }
.spark .pt.pass { fill: var(--ink); }
.spark .pt.fail { fill: var(--red); }
.spark text { font-family: var(--mono); font-size: 10px; fill: var(--faint); }
.pgrid { display: flex; flex-direction: column; gap: 10px; margin-top: 4px; }
.prow { display: grid; grid-template-columns: minmax(150px, 1.4fr) 2fr auto; gap: 12px; align-items: center; font-size: 13.5px; }
.pbar { height: 4px; background: var(--line); overflow: hidden; }
.pbar i { display: block; height: 100%; background: var(--ink); }
.pbar i.mid { background: var(--amber); }
.pbar i.bad { background: var(--red); }
.pnum { font-family: var(--mono); font-size: 12.5px; color: var(--muted); white-space: nowrap; }
.pnum b { color: var(--ink); font-weight: 500; }
.missed { border: 1px solid var(--line); border-radius: var(--r); margin-bottom: 8px; overflow: hidden; }
.missed-head { display: flex; gap: 12px; align-items: flex-start; width: 100%; text-align: left; font-size: 14px; background: transparent; border: 0; padding: 12px 14px; cursor: pointer; }
.missed-head:hover { background: var(--panel); }
.missed-head .qmod { flex: 0 0 auto; margin-top: 2px; font-family: var(--mono); color: var(--faint); }
.missed-head .mstem { flex: 1; color: var(--ink); }
.missed-head .tag { flex: 0 0 auto; }
.missed-body { padding: 2px 16px 16px; border-top: 1px solid var(--line); }
.missed-body .stem { font-size: 16px; margin-top: 12px; }

/* practice tally */
.tally { font-size: 14px; color: var(--muted); }
.tally b { font-family: var(--mono); font-size: 16px; font-weight: 500; }

/* ---------- modal & toast ---------- */
.modal-back { position: fixed; inset: 0; background: rgba(0, 0, 0, .4); z-index: 50; display: flex; align-items: center; justify-content: center; padding: 20px; }
.modal { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r); max-width: 460px; width: 100%; padding: 24px 26px; }
.modal h3 { margin: 0 0 8px; font-size: 18px; font-weight: 600; color: var(--ink); }
.modal p { margin: 6px 0; font-size: 14px; line-height: 1.55; }
.modal .warn { color: var(--amber); font-weight: 600; }
.modal .actions { justify-content: flex-end; }
.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); z-index: 60;
  background: var(--accent); color: var(--accent-ink); padding: 9px 16px; border-radius: var(--r); font-size: 13.5px;
  opacity: 0; transition: opacity .25s;
}
.toast.show { opacity: 1; }

@media (max-width: 640px) {
  .wrap { padding: 16px 16px 56px; }
  .card, .qcard { padding: 20px 18px; }
  .banner .score { margin-left: 0; }
  .prow, .dotrow { grid-template-columns: 1fr; gap: 4px; }
  .stem { font-size: 16.5px; }
}

.scope-note { color: var(--muted); font-size: 14px; }
.exam-history { margin-top: 24px; }
.exam-history > summary { cursor: pointer; font-weight: 600; padding: 12px 0; }

/* Shared publication vocabulary, preserving the application's existing states. */
body{background:var(--frame);font-size:16px;line-height:1.7}::selection{background:#d3e3ef;color:#173f63}a{color:var(--ink);text-underline-offset:4px}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible{outline:2px solid var(--ink);outline-offset:4px}.wrap{max-width:1200px;padding:30px 32px 72px}.topbar .wrap{padding-top:18px;padding-bottom:18px}.brand .t1{font-family:Georgia,"Times New Roman","Microsoft JhengHei",serif;font-size:19px;font-weight:400}.brand .t2{font-size:12px;letter-spacing:0;text-transform:none;color:var(--muted);margin-top:5px}.study-entry{font-size:13px;padding:4px 12px;text-decoration:none;border-right:1px solid var(--line)}.topctl{gap:12px}.seg{border-color:transparent;border-radius:3px}.seg button{font-size:12px;padding:5px 9px}.card,.qcard{border:0;border-radius:0;background:var(--bg);padding:32px 36px;box-shadow:0 10px 28px #173f6308}.card h2{font-size:23px;margin-bottom:12px}.card .sub{font-size:15px;line-height:1.8;max-width:75ch}.card .rulebox{background:var(--amber-bg);border-radius:0;padding:18px 20px;line-height:1.8}.subhead,.eyebrow,.tlabel,.omr-mod{letter-spacing:0;text-transform:none;font-size:12px;color:var(--muted)}.stem{font-size:20px;line-height:1.75;margin:18px 0 14px;max-width:68ch}.stmts{margin-top:20px}.stmts li{font-size:17px;line-height:1.8;padding-left:32px;margin-top:12px}.stmts li::before{font-family:var(--sans);font-size:14px;line-height:2.1}.opts{gap:0;margin-top:30px}.opt{border:0;border-top:1px solid var(--line);border-radius:0;font-size:16px;line-height:1.7;padding:16px 12px;background:var(--bg)}.opt:last-child{border-bottom:1px solid var(--line)}.opt:hover{background:var(--panel)}.opt .letter{font-family:var(--sans);border:0;border-radius:3px;font-size:14px;font-weight:600}.opt.sel{background:var(--panel)}.opt.correct{background:var(--green-bg)}.opt.wrong{background:var(--red-bg)}.opt.dim{opacity:1;color:var(--muted)}.explain{background:var(--panel);border-radius:0;padding:22px 24px;font-size:16px;line-height:1.8}.explain .cite{font-family:var(--sans);font-size:13px;line-height:1.8;border-top:1px solid var(--line);padding-top:16px;margin-top:20px}.source-files{margin-top:10px}.source-file{margin-top:7px;overflow-wrap:anywhere}.source-file a{color:var(--muted);text-decoration-color:var(--line-strong)}.st-note{font-size:15px;line-height:1.8;padding-top:6px}.st-verdict{font-size:14px;margin-top:8px}.question-map{color:var(--muted)}.chip{border-radius:3px;padding:9px 14px;font-size:14px;background:var(--bg)}button.btn{font-size:14px;padding:10px 18px;border-radius:3px}.qmeta{border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:24px}.qmod{font-size:13px;line-height:1.6}.qnum{font-size:20px}.footer{font-size:13px;color:var(--muted)}.banner{background:var(--bg);border:0;border-radius:0}.profile-card{background:var(--bg)}.examgrid{gap:28px}.rail .card{box-shadow:none}.exam-history>summary{color:var(--ink)}.modal{box-shadow:0 20px 60px #10243e24}.scope-note{font-size:14px}.optrow{line-height:1.8}.qflag{border-radius:3px}.tcline{line-height:1.8}.welcome{padding:44px}.welcome h2{font-size:28px}.modal p{font-size:15px;line-height:1.8}
@media(min-width:960px){.examgrid{grid-template-columns:minmax(0,1fr) 388px}.rail{top:100px;max-height:calc(100vh - 116px)}}
@media(max-width:640px){.wrap{padding:20px 14px 52px}.topbar .wrap{padding:14px 16px;gap:12px}.brand{min-width:0;flex-basis:100%}.brand .t1{font-size:17px}.brand .t2{font-size:11px}.topctl{gap:4px}.study-entry{font-size:12px;padding-left:0;padding-right:10px}.seg button{font-size:12px;padding:4px 7px}.card,.qcard{padding:24px 20px}.card h2{font-size:22px}.stem{font-size:18px;line-height:1.8}.stmts li{font-size:16px}.opt{font-size:16px;padding:14px 6px}.explain{padding:18px 16px}.qmeta{gap:10px}.qmod{font-size:12px;overflow-wrap:anywhere}.qnum{font-size:18px}.tally{font-size:12px}.chip{font-size:13px;padding:8px 10px}.rulebox{padding:16px!important}.dotrow,.prow{gap:8px}.tablewrap{max-width:100%}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

:root[data-theme="dark"] .opt.correct .letter,:root[data-theme="dark"] .opt.wrong .letter{color:#10202a}
